class AccessibilityManager {
  constructor() {
    this._labelRegistry = new WeakMap();
    this._liveRegions = new Map();
    this._focusTrapStack = [];
    this._init();
  }

  _init() {
    const polite = document.createElement('div');
    polite.setAttribute('aria-live', 'polite');
    polite.setAttribute('aria-atomic', 'true');
    polite.className = 'visually-hidden';
    polite.id = 'ds-live-polite';

    const assertive = document.createElement('div');
    assertive.setAttribute('aria-live', 'assertive');
    assertive.setAttribute('aria-atomic', 'true');
    assertive.className = 'visually-hidden';
    assertive.id = 'ds-live-assertive';

    document.body.appendChild(polite);
    document.body.appendChild(assertive);

    this._liveRegions.set('polite', polite);
    this._liveRegions.set('assertive', assertive);
  }

  requireLabel(element, context) {
    const label = element.getAttribute('aria-label') ||
      element.getAttribute('aria-labelledby') ||
      element.textContent.trim();

    if (!label) {
      const msg = `[GlassDesignSystem] Accessibility violation: ${context || element.tagName} has no accessible label. Set aria-label or provide visible text content.`;
      console.error(msg);
      element.setAttribute('data-a11y-error', 'missing-label');
      return false;
    }
    return true;
  }

  enforceIconLabel(element) {
    const isIconOnly = element.classList.contains('ds-button--icon-only') ||
      element.dataset.iconOnly === 'true' ||
      element.classList.contains('ds-toolbar__item--icon-only');

    if (isIconOnly) {
      const hasLabel = element.getAttribute('aria-label') ||
        element.getAttribute('title');

      if (!hasLabel) {
        const msg = `[GlassDesignSystem] Accessibility violation: icon-only element requires aria-label.`;
        console.error(msg, element);
        element.setAttribute('data-a11y-error', 'icon-no-label');
        return false;
      }

      const visuallyHidden = element.querySelector('.visually-hidden');
      if (!visuallyHidden) {
        const span = document.createElement('span');
        span.className = 'visually-hidden';
        span.textContent = element.getAttribute('aria-label') || element.getAttribute('title');
        element.appendChild(span);
      }
    }
    return true;
  }

  announce(message, priority = 'polite') {
    const region = this._liveRegions.get(priority);
    if (!region) return;
    region.textContent = '';
    requestAnimationFrame(() => {
      region.textContent = message;
    });
  }

  trapFocus(container) {
    const focusable = this._getFocusableElements(container);
    if (!focusable.length) return () => {};

    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    const previousFocus = document.activeElement;

    first.focus();

    const handleKeydown = (e) => {
      if (e.key !== 'Tab') return;
      if (e.shiftKey) {
        if (document.activeElement === first) {
          e.preventDefault();
          last.focus();
        }
      } else {
        if (document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    };

    container.addEventListener('keydown', handleKeydown);
    this._focusTrapStack.push({ container, handleKeydown, previousFocus });

    return () => {
      container.removeEventListener('keydown', handleKeydown);
      const idx = this._focusTrapStack.findIndex(t => t.container === container);
      if (idx !== -1) {
        this._focusTrapStack.splice(idx, 1);
        if (previousFocus && document.contains(previousFocus)) {
          previousFocus.focus();
        }
      }
    };
  }

  releaseFocusTrap(container) {
    const trap = this._focusTrapStack.find(t => t.container === container);
    if (!trap) return;
    container.removeEventListener('keydown', trap.handleKeydown);
    const idx = this._focusTrapStack.indexOf(trap);
    this._focusTrapStack.splice(idx, 1);
    if (trap.previousFocus && document.contains(trap.previousFocus)) {
      trap.previousFocus.focus();
    }
  }

  _getFocusableElements(container) {
    const selectors = [
      'a[href]',
      'button:not([disabled])',
      'input:not([disabled])',
      'select:not([disabled])',
      'textarea:not([disabled])',
      '[tabindex]:not([tabindex="-1"])',
      '[contenteditable]',
    ].join(', ');
    return Array.from(container.querySelectorAll(selectors)).filter(el => {
      return !el.closest('[hidden]') && el.offsetParent !== null;
    });
  }

  makeInteractive(element, options = {}) {
    const { label, role, description, expanded, controls } = options;

    if (role) element.setAttribute('role', role);
    if (label) element.setAttribute('aria-label', label);
    if (description) element.setAttribute('aria-description', description);
    if (expanded !== undefined) element.setAttribute('aria-expanded', String(expanded));
    if (controls) element.setAttribute('aria-controls', controls);

    if (!element.getAttribute('tabindex') && !['button', 'a', 'input', 'select', 'textarea'].includes(element.tagName.toLowerCase())) {
      element.setAttribute('tabindex', '0');
    }

    element.addEventListener('keydown', (e) => {
      if ((e.key === 'Enter' || e.key === ' ') && element.getAttribute('role') !== 'textbox') {
        if (options.onActivate) {
          e.preventDefault();
          options.onActivate(e);
        }
      }
      if (e.key === 'Escape' && options.onDismiss) {
        e.preventDefault();
        options.onDismiss(e);
      }
    });

    return this;
  }

  setExpanded(element, value) {
    element.setAttribute('aria-expanded', String(value));
  }

  setDisabled(element, value) {
    element.setAttribute('aria-disabled', String(value));
    if (value) {
      element.setAttribute('tabindex', '-1');
    } else {
      element.removeAttribute('tabindex');
    }
  }

  setChecked(element, value) {
    element.setAttribute('aria-checked', String(value));
  }

  setSelected(element, value) {
    element.setAttribute('aria-selected', String(value));
  }

  setPressed(element, value) {
    element.setAttribute('aria-pressed', String(value));
  }

  setValueNow(element, value, min, max) {
    element.setAttribute('aria-valuenow', String(value));
    if (min !== undefined) element.setAttribute('aria-valuemin', String(min));
    if (max !== undefined) element.setAttribute('aria-valuemax', String(max));
    element.setAttribute('aria-valuetext', String(value));
  }

  setHidden(element, value) {
    element.setAttribute('aria-hidden', String(value));
  }

  registerListNavigation(container, options = {}) {
    const { orientation = 'vertical', wrap = true, onSelect } = options;

    container.addEventListener('keydown', (e) => {
      const items = this._getFocusableElements(container);
      const current = document.activeElement;
      const idx = items.indexOf(current);

      let nextIdx = idx;
      const isVertical = orientation === 'vertical';

      if ((isVertical && e.key === 'ArrowDown') || (!isVertical && e.key === 'ArrowRight')) {
        e.preventDefault();
        nextIdx = idx + 1 >= items.length ? (wrap ? 0 : idx) : idx + 1;
      } else if ((isVertical && e.key === 'ArrowUp') || (!isVertical && e.key === 'ArrowLeft')) {
        e.preventDefault();
        nextIdx = idx - 1 < 0 ? (wrap ? items.length - 1 : 0) : idx - 1;
      } else if (e.key === 'Home') {
        e.preventDefault();
        nextIdx = 0;
      } else if (e.key === 'End') {
        e.preventDefault();
        nextIdx = items.length - 1;
      }

      if (nextIdx !== idx && items[nextIdx]) {
        items[nextIdx].focus();
        if (onSelect) onSelect(items[nextIdx], nextIdx);
      }
    });
  }
}

const a11y = new AccessibilityManager();

export { AccessibilityManager, a11y };

