class AccessibilityManager {
  constructor() {
    this._liveRegions = new Map();
    this._focusTrapStack = [];
    this._interactiveHandlers = new WeakMap();
    this._tabIndexRegistry = new WeakMap();

    if (typeof document !== 'undefined' && document.body) {
      this._init();
    }
  }

  _init() {
    this._createLiveRegion('polite');
    this._createLiveRegion('assertive');
  }

  _createLiveRegion(priority) {
    const id = `ds-live-${priority}`;
    let region = document.getElementById(id);

    if (!region) {
      region = document.createElement('div');
      region.id = id;
      region.className = 'visually-hidden';
      region.setAttribute('aria-live', priority);
      region.setAttribute('aria-atomic', 'true');
      region.setAttribute('role', priority === 'assertive' ? 'alert' : 'status');
      document.body.appendChild(region);
    }

    this._liveRegions.set(priority, region);
  }

  _isElement(value) {
    return typeof Element !== 'undefined' && value instanceof Element;
  }

  _isNativeInteractive(element) {
    if (!this._isElement(element)) {
      return false;
    }

    const tagName = element.tagName.toLowerCase();

    if (tagName === 'a') {
      return element.hasAttribute('href');
    }

    return [
      'button',
      'input',
      'select',
      'textarea',
      'summary',
      'audio',
      'video',
      'iframe',
    ].includes(tagName);
  }

  _isNativeDisableable(element) {
    if (!this._isElement(element)) {
      return false;
    }

    return ['button', 'input', 'select', 'textarea', 'fieldset', 'optgroup', 'option'].includes(
      element.tagName.toLowerCase(),
    );
  }

  _getReferencedLabelText(element) {
    const labelledBy = element.getAttribute('aria-labelledby');

    if (!labelledBy || typeof document === 'undefined') {
      return '';
    }

    return labelledBy
      .trim()
      .split(/\s+/)
      .map((id) => document.getElementById(id))
      .filter((labelElement) => labelElement)
      .map((labelElement) => labelElement.textContent.trim())
      .filter(Boolean)
      .join(' ');
  }

  _getAccessibleLabel(element) {
    if (!this._isElement(element)) {
      return '';
    }

    const ariaLabel = element.getAttribute('aria-label');

    if (ariaLabel && ariaLabel.trim()) {
      return ariaLabel.trim();
    }

    const referencedLabel = this._getReferencedLabelText(element);

    if (referencedLabel) {
      return referencedLabel;
    }

    return element.textContent ? element.textContent.trim() : '';
  }

  _isHidden(element) {
    if (!this._isElement(element)) {
      return true;
    }

    if (element.closest('[hidden], [aria-hidden="true"], [inert]')) {
      return true;
    }

    const style = typeof window !== 'undefined' ? window.getComputedStyle(element) : null;

    if (!style) {
      return false;
    }

    return style.display === 'none' || style.visibility === 'hidden';
  }

  _isFocusable(element) {
    if (!this._isElement(element) || this._isHidden(element)) {
      return false;
    }

    if (element.matches(':disabled')) {
      return false;
    }

    if (element.getAttribute('aria-disabled') === 'true') {
      return false;
    }

    if (element.matches('[contenteditable="false"]')) {
      return false;
    }

    const tabIndex = element.getAttribute('tabindex');

    if (tabIndex !== null && Number.parseInt(tabIndex, 10) < 0) {
      return false;
    }

    return element.matches(
      'a[href], button, input, select, textarea, summary, iframe, audio[controls], video[controls], [contenteditable]:not([contenteditable="false"]), [tabindex]',
    );
  }

  _getFocusableElements(container) {
    if (!this._isElement(container)) {
      return [];
    }

    const selectors = [
      'a[href]',
      'button',
      'input',
      'select',
      'textarea',
      'summary',
      'iframe',
      'audio[controls]',
      'video[controls]',
      '[tabindex]',
      '[contenteditable]:not([contenteditable="false"])',
    ].join(', ');

    return Array.from(container.querySelectorAll(selectors)).filter((element) =>
      this._isFocusable(element),
    );
  }

  _getFocusTrap(container) {
    for (let index = this._focusTrapStack.length - 1; index >= 0; index -= 1) {
      const trap = this._focusTrapStack[index];

      if (trap.container === container) {
        return { trap, index };
      }
    }

    return null;
  }

  _restoreFocus(previousFocus) {
    if (this._isElement(previousFocus) && document.contains(previousFocus)) {
      previousFocus.focus();
    }
  }

  requireLabel(element, context) {
    if (!this._isElement(element)) {
      throw new TypeError('requireLabel expects a DOM Element.');
    }

    const label = this._getAccessibleLabel(element);

    if (!label) {
      const message = `[GlassDesignSystem] Accessibility violation: ${
        context || element.tagName
      } has no accessible label. Set aria-label, reference valid aria-labelledby content, or provide visible text content.`;

      console.error(message);
      element.setAttribute('data-a11y-error', 'missing-label');
      return false;
    }

    element.removeAttribute('data-a11y-error');
    return true;
  }

  enforceIconLabel(element) {
    if (!this._isElement(element)) {
      throw new TypeError('enforceIconLabel expects a DOM Element.');
    }

    const isIconOnly =
